// Boot-time guard for the db-push -> migrate cutover.
//
// Situation it handles: migration files exist in the image (the
// *_init baseline generated by scripts/migrate-baseline.*), but the
// database was built by the legacy `prisma db push` boot and has no
// `_prisma_migrations` history. Letting `migrate deploy` run in that
// state would try to re-CREATE every table and fail. The fix is the
// standard Prisma baseline step (`migrate resolve --applied <init>`),
// which only records a row in `_prisma_migrations` — it touches no
// data. This script runs that step automatically, exactly once.
//
// Decision table (checked live against the connected DB):
//   schema present + no migration history  -> resolve init as applied
//   schema present + history exists        -> no-op
//   fresh/empty DB                         -> no-op (migrate deploy
//                                             will create everything
//                                             from the migration files)
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

async function main() {
    const migrationsDir = path.join(__dirname, '..', 'prisma', 'migrations');
    let initDir = null;
    try {
        initDir = fs
            .readdirSync(migrationsDir)
            .find(
                (d) =>
                    d.endsWith('_init') &&
                    fs.existsSync(
                        path.join(migrationsDir, d, 'migration.sql'),
                    ),
            );
    } catch {
        return; // no migrations dir at all -> db push fallback path
    }
    if (!initDir) return;

    const { PrismaClient } = require('@prisma/client');
    const prisma = new PrismaClient();
    try {
        // Does the app schema exist? (User is the oldest core table.)
        // ::text cast — Prisma can't deserialize the raw `regclass` type.
        const schemaRows = await prisma.$queryRawUnsafe(
            `SELECT to_regclass('public."User"')::text AS t`,
        );
        const schemaExists = schemaRows?.[0]?.t != null;
        if (!schemaExists) return; // fresh DB -> let migrate deploy build it

        // Is there already migration history?
        const histRows = await prisma.$queryRawUnsafe(
            `SELECT to_regclass('public._prisma_migrations')::text AS t`,
        );
        let applied = 0;
        if (histRows?.[0]?.t != null) {
            const cnt = await prisma.$queryRawUnsafe(
                `SELECT COUNT(*)::int AS n FROM "_prisma_migrations" WHERE finished_at IS NOT NULL`,
            );
            applied = cnt?.[0]?.n || 0;
        }
        if (applied > 0) return; // already baselined

        console.log(
            `[boot] Existing schema without migration history detected — ` +
                `marking ${initDir} as applied (baseline, no data touched).`,
        );
        execSync(`npx prisma migrate resolve --applied ${initDir}`, {
            stdio: 'inherit',
        });
    } finally {
        await prisma.$disconnect();
    }
}

main().catch((err) => {
    console.error('[boot] ensure-baseline failed:', err.message);
    process.exit(1);
});
